// Parse the find-creators request
const body = $input.first().json.body || $input.first().json;
const requirements = {
  project_id: body.project_id || '',
  niches: Array.isArray(body.niches) ? body.niches : (body.niches || '').split(',').map(s => s.trim()).filter(Boolean),
  languages: Array.isArray(body.languages) ? body.languages : (body.languages || 'English').split(',').map(s => s.trim()).filter(Boolean),
  gender: body.gender || '',
  budget_max: Number(body.budget_max) || 50000,
  style: body.style || '',
  brand_name: body.brand_name || '',
  industry: body.industry || '',
  count: Number(body.count) || 5
};
return [{ json: requirements }];

// Score and rank creators based on requirements
const requirements = $('Parse Requirements').first().json;
const creatorsResponse = $input.first().json;
const creators = (creatorsResponse.records || []).map(r => ({ id: r.id, ...r.fields }));

if (creators.length === 0) {
  return [{ json: { matches: [], message: 'No available creators in database', requirements } }];
}

// Score each creator
const scored = creators.map(creator => {
  let score = 0;
  const reasons = [];

  // Niche match (highest weight)
  const creatorNiches = Array.isArray(creator.niches) ? creator.niches : [];
  const nicheMatches = requirements.niches.filter(n => creatorNiches.includes(n));
  if (nicheMatches.length > 0) {
    score += 30 * nicheMatches.length;
    reasons.push(`Niche: ${nicheMatches.join(', ')}`);
  }

  // Language match
  const creatorLangs = Array.isArray(creator.languages) ? creator.languages : [];
  const langMatches = requirements.languages.filter(l => creatorLangs.includes(l));
  if (langMatches.length > 0) {
    score += 20 * langMatches.length;
    reasons.push(`Language: ${langMatches.join(', ')}`);
  }

  // Gender match
  if (requirements.gender && creator.gender === requirements.gender) {
    score += 15;
    reasons.push(`Gender: ${creator.gender}`);
  }

  // Budget match
  const rate = creator.rate_per_video || 0;
  if (rate > 0 && rate <= requirements.budget_max) {
    score += 10;
    reasons.push(`Rate: \u20b9${rate} (within budget)`);
  } else if (rate > requirements.budget_max) {
    score -= 10;
    reasons.push(`Rate: \u20b9${rate} (over budget)`);
  }

  // Rating bonus
  const rating = creator.rating || 0;
  if (rating >= 4) {
    score += rating * 3;
    reasons.push(`Rating: ${rating}/5`);
  }

  // Experience bonus
  const totalShot = creator.total_scripts_shot || 0;
  if (totalShot > 10) {
    score += 5;
    reasons.push(`${totalShot} scripts shot`);
  }

  return {
    ...creator,
    score,
    match_reasons: reasons
  };
});

// Sort by score descending, take top N
scored.sort((a, b) => b.score - a.score);
const topMatches = scored.slice(0, requirements.count);

return [{ json: { 
  matches: topMatches.map(c => ({
    id: c.id,
    name: c.name,
    instagram: c.instagram_handle,
    portfolio: c.portfolio_url,
    niches: c.niches,
    languages: c.languages,
    gender: c.gender,
    rate_per_video: c.rate_per_video,
    rating: c.rating,
    total_scripts: c.total_scripts_shot,
    score: c.score,
    match_reasons: c.match_reasons
  })),
  total_available: creators.length,
  requirements
} }];

