  `site:instagram.com ${niche} influencer micro creator ${location} brand collaboration`,
  `instagram ${niche} UGC content creator ${location} affordable collaboration DM`
];

return [{ json: { 
  queries, niche, location, count, budget, brand, requirements, languages,
