}}];

const results = $input.all().map(item => item.json);
const brief = $('Build Search Queries').first().json;

const allProfiles = [];
const seen = new Set();

for (const result of results) {
  const organic = result.organic_results || [];
  for (const r of organic) {
    const url = r.link || '';
    const title = r.title || '';
    const snippet = r.snippet || '';

    // Match Instagram profile URLs
    const igMatch = url.match(/instagram\.com\/([a-zA-Z0-9._]+)/);
    if (!igMatch) continue;

    const handle = igMatch[1].toLowerCase();

    // Skip common non-creator accounts
    const skipList = ['explore', 'p', 'reel', 'stories', 'accounts', 'tags', 'locations', 'reels', 'about', 'directory', 'developer', 'legal', 'help'];
    if (skipList.includes(handle)) continue;
    if (seen.has(handle)) continue;
    seen.add(handle);

    allProfiles.push({
      instagram_handle: '@' + handle,
      profile_url: `https://instagram.com/${handle}`,
      name: title.replace(/\(.*?\)/g, '').replace(/@\w+/g, '').replace(/\u2022\s*Instagram.*$/i, '').replace(/\|.*$/i, '').trim().split(' - ')[0].trim(),
      bio_snippet: snippet,
      source_url: url
    });
  }
}

// Dedup against existing creators in Airtable
// Fetch current handles from the DB
