try {
  const resp = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://api.airtable.com/v0/appvFxwZc9yU8o8pK/tbl59nWGcoucE0gjf?fields%5B%5D=instagram_handle&pageSize=100',
    headers: {
      'Authorization': 'Bearer ' + 'AIRTABLE_PAT_INJECTED_AT_DEPLOY'
    },
    json: true
  });
  const records = resp.records || [];
  for (const r of records) {
    const h = (r.fields.instagram_handle || '').replace('@', '').toLowerCase();
    if (h) existingHandles.add(h);
  }
  // Handle pagination
  let offset = resp.offset;
  while (offset) {
    const nextResp = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://api.airtable.com/v0/appvFxwZc9yU8o8pK/tbl59nWGcoucE0gjf?fields%5B%5D=instagram_handle&pageSize=100&offset=' + offset,
      headers: {
        'Authorization': 'Bearer ' + 'AIRTABLE_PAT_INJECTED_AT_DEPLOY'
      },
      json: true
    });
    for (const r of (nextResp.records || [])) {
      const h = (r.fields.instagram_handle || '').replace('@', '').toLowerCase();
      if (h) existingHandles.add(h);
    }
    offset = nextResp.offset;
  }
