    name: p.name,
    niche_score: 5,
    creator_score: 5,
    rate_compatible: true,
    content_signals: p.bio_snippet,
    recommended: true,
    instagram_dm: `Hey! Love your content. We are looking for creators for a ${brief.niche} brand campaign. Budget is Rs.${brief.budget}/video. Interested?`,
    email_subject: `Creator Collaboration - ${brief.niche} Brand Campaign`,
    email_body: `Hi ${p.name},\n\nI found your profile on Instagram and love your content in the ${brief.niche} space.\n\nWe are a creative agency looking for UGC creators for an upcoming brand campaign. Budget is Rs.${brief.budget} per video.\n\nWould you be interested in collaborating?\n\nBest regards,\nSmashed Agency`
  }));
}

// Sort by combined score, take top N
const ranked = creators
  .filter(c => c.recommended !== false)
  .sort((a, b) => ((b.niche_score || 0) + (b.creator_score || 0)) - ((a.niche_score || 0) + (a.creator_score || 0)))
  .slice(0, brief.count + 3);

// Merge with raw profile data
const enriched = ranked.map(c => {
  const raw = rawProfiles.find(p => p.instagram_handle === c.handle || p.instagram_handle === (c.handle || '').replace('@', '') || ('@' + (p.instagram_handle || '').replace('@', '')) === c.handle);
  return {
    ...c,
    profile_url: raw?.profile_url || `https://instagram.com/${(c.handle || '').replace('@', '')}`,
    source_url: raw?.source_url || '',
    bio_snippet: raw?.bio_snippet || c.content_signals || ''
  };
});

return [{ json: {
  creators: enriched,
  count: enriched.length,
  brief
}}];

const data = $input.first().json;
const creators = data.creators;
const brief = data.brief;

// Build Airtable batch create payload
// Only include fields with known valid select options
const records = creators.map(c => {
  const fields = {
    name: c.name || (c.handle || '').replace('@', ''),
    instagram_handle: c.handle || '',
    location: brief.location || '',
    rate_per_video: brief.budget || 0,
    status: 'Active',
    availability: 'Available',
    notes: `Sourced via Creator Scout v2 | Niche: ${brief.niche} | Score: ${(c.niche_score || 0) + (c.creator_score || 0)}/20 | Brand: ${brief.brand || 'N/A'} | ${c.content_signals || ''}`
  };
  // Only add languages that exist as options
  const validLangs = (brief.languages || []).filter(l => ['English', 'Hindi'].includes(l));
  if (validLangs.length > 0) fields.languages = validLangs;
  return { fields };
});

// Airtable batch API: max 10 records per request
// Output each batch as a separate item so the HTTP Request node processes them all
const items = [];
for (let i = 0; i < records.length; i += 10) {
  const batch = records.slice(i, i + 10);
  items.push({ json: {
    airtable_body: JSON.stringify({ records: batch }),
    batchIndex: Math.floor(i / 10),
    batchCount: Math.ceil(records.length / 10),
    creators: data.creators,
    brief,
    totalRecords: records.length
  }});
}

if (items.length === 0) {
  return [{ json: { airtable_body: JSON.stringify({ records: [] }), batchCount: 0, creators: data.creators, brief, totalRecords: 0 } }];
}

return items;

